<?php require APPROOT.'/views/inc/header.php'; ?><div class="app-content"><div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Reclutamiento</h1><p class="text-secondary mb-0">Vacantes, pipeline y ranking asistido con revisión humana.</p></div><a class="btn btn-outline-primary" href="<?= URLROOT ?>/careers" target="_blank">Ver portal público</a></div><?php if(!empty($_SESSION['flash_error'])):?><div class="alert alert-danger"><?= htmlspecialchars($_SESSION['flash_error']);unset($_SESSION['flash_error']); ?></div><?php endif;?><?php if(!empty($_SESSION['flash_success'])):?><div class="alert alert-success"><?= htmlspecialchars($_SESSION['flash_success']);unset($_SESSION['flash_success']); ?></div><?php endif;?><div class="row g-4"><section class="col-xl-4"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Nueva vacante</h2><form method="post" action="<?= URLROOT ?>/recruiting/saveVacancy"><?= csrf_field() ?><label class="form-label">Título</label><input class="form-control mb-3" name="title" required><label class="form-label">Descripción pública</label><textarea class="form-control mb-3" rows="5" name="description" required></textarea><label class="form-label">Criterios publicados (uno por línea)</label><textarea class="form-control mb-3" rows="4" name="criteria" required></textarea><label class="form-label">Etapas (una por línea)</label><textarea class="form-control mb-3" rows="4" name="pipeline">received&#10;shortlist&#10;interview&#10;offer&#10;hired&#10;rejected</textarea><label class="form-label">Cierre</label><input type="date" class="form-control mb-3" name="closes_at"><select class="form-select mb-3" name="status"><option value="draft">Borrador</option><option value="published">Publicar</option></select><button class="btn btn-primary w-100">Guardar vacante</button></form></div></div></section><section class="col-xl-8"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Vacantes</h2><div class="list-group list-group-flush"><?php foreach($d['vacancies'] as $v): ?><a class="list-group-item list-group-item-action d-flex justify-content-between <?= (int)$d['selected']===(int)$v->id?'active':'' ?>" href="<?= URLROOT ?>/recruiting/index?vacancy_id=<?= (int)$v->id ?>"><span><?= htmlspecialchars($v->title) ?><small class="d-block opacity-75"><?= htmlspecialchars($v->status) ?></small></span><span class="badge text-bg-light align-self-center"><?= (int)$v->application_count ?></span></a><?php endforeach; ?></div></div></div><?php if($d['selected']): ?><div class="card border-0 shadow-sm mt-4"><div class="card-body"><h2 class="h5">Postulaciones</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Candidato</th><th>Etapa</th><th>IA</th><th>Acciones</th></tr></thead><tbody><?php foreach($d['applications'] as $a): $result=json_decode($a->ai_result_json??'',true); ?><tr><td><strong><?= htmlspecialchars($a->full_name) ?></strong><small class="d-block text-secondary"><?= htmlspecialchars($a->email) ?></small></td><td><form class="d-flex gap-2" method="post" action="<?= URLROOT ?>/recruiting/move/<?= (int)$a->id ?>"><?= csrf_field() ?><input class="form-control form-control-sm" name="stage" value="<?= htmlspecialchars($a->current_stage) ?>"><button class="btn btn-sm btn-outline-primary">Mover</button></form></td><td><?= $a->ai_score!==null?'<strong>'.number_format($a->ai_score,1).'</strong>':'—' ?><?php if($result):?><small class="d-block text-secondary" title="<?= htmlspecialchars($result['explanation']??'') ?>">Con evidencia</small><?php endif;?></td><td><div class="d-flex flex-wrap gap-1"><a class="btn btn-sm btn-outline-secondary" href="<?= URLROOT ?>/recruiting/downloadCv/<?= (int)$a->id ?>">CV</a><form method="post" action="<?= URLROOT ?>/recruiting/score/<?= (int)$a->id ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-primary">Analizar IA</button></form><form method="post" action="<?= URLROOT ?>/recruiting/onboard/<?= (int)$a->id ?>" onsubmit="return confirm('¿Crear preingreso?')"><?= csrf_field() ?><button class="btn btn-sm btn-success">Preingreso</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php endif;?></section></div></div></div><?php require APPROOT.'/views/inc/footer.php'; ?>
